mapper.insert:
INSERT INTO LISTING_OPTION (
    LSTG_ID,
    FAC_OPT_ID
)
VALUES

    (
        #{opt.lstgId},
        #{opt.facOptId}
    )

mapper.select:
  SELECT COUNT(*)
  FROM LISTING L
  WHERE L.LSTG_DEL = 'N'
    
      AND L.MBR_CD = #{pagingVO.detailSearch.mbrCd}

      
        AND L.LSTG_NM LIKE '%' || #{pagingVO.detailSearch.searchBuildingName} || '%'
      

      
        AND L.LSTG_ROOM_NUM LIKE '%' || #{pagingVO.detailSearch.searchRoomNum} || '%'
      

      
        AND L.LSTG_PROD_STAT = #{pagingVO.detailSearch.searchStatus}
      

      
        AND L.LSTG_TYPE_SALE = #{pagingVO.detailSearch.searchType}

        
        
          
            AND L.LSTG_LEASE >= #{pagingVO.detailSearch.searchDepositMin}
          
          
            AND L.LSTG_LEASE <= #{pagingVO.detailSearch.searchDepositMax}
          
        

        
        
          
            AND L.LSTG_LEASE_AMT >= #{pagingVO.detailSearch.searchDepositMin}
          
          
            AND L.LSTG_LEASE_AMT <= #{pagingVO.detailSearch.searchDepositMax}
          
          
            AND L.LSTG_LEASE_M >= #{pagingVO.detailSearch.searchMonthlyMin}
          
          
            AND L.LSTG_LEASE_M <= #{pagingVO.detailSearch.searchMonthlyMax}
          
        

        
        
          
            AND L.LSTG_SALE >= #{pagingVO.detailSearch.searchSaleMin}
          
          
            AND L.LSTG_SALE <= #{pagingVO.detailSearch.searchSaleMax}
          
        
      
      
		  AND L.LSTG_REG_DATE >= TO_DATE(#{pagingVO.detailSearch.searchRegDateFrom}, 'YYYY-MM-DD')
		
		
		  AND L.LSTG_REG_DATE <= TO_DATE(#{pagingVO.detailSearch.searchRegDateTo}, 'YYYY-MM-DD') + 1
		
      
    
   ORDER BY L.LSTG_REG_DATE, L.LSTG_ID

SELECT A_PAGING.LSTG_ID, A_PAGING.MBR_CD, A_PAGING.LSTG_TYPE_CODE2, A_PAGING.LSTG_ADD, A_PAGING.LSTG_ADD2, A_PAGING.LSTG_EX_AREA, A_PAGING.LSTG_GR_AREA, A_PAGING.LSTG_ROOM_CNT, A_PAGING.LSTG_ROOM_NUM, A_PAGING.LSTG_DST, A_PAGING.LSTG_TYPE_SALE, A_PAGING.LSTG_LEASE, A_PAGING.LSTG_LEASE_M, A_PAGING.LSTG_LEASE_AMT, A_PAGING.LSTG_FLOOR, A_PAGING.LSTG_PARK_YN, A_PAGING.LSTG_LAT, A_PAGING.LSTG_LNG, A_PAGING.LSTG_DEL, A_PAGING.LSTG_REG_DATE, A_PAGING.LSTG_PROD_STAT, A_PAGING.LSTG_NM, A_PAGING.LSTG_TYPE_CODE1, A_PAGING.RENTAL_PTY_ID, A_PAGING.LSTG_POSTAL, A_PAGING.LSTG_FEE FROM ( SELECT ROW_NUMBER() OVER (ORDER BY L.LSTG_REG_DATE DESC) AS RNUM, L.LSTG_ID, L.MBR_CD, L.LSTG_TYPE_CODE2, L.LSTG_ADD, L.LSTG_ADD2, L.LSTG_EX_AREA, L.LSTG_GR_AREA, L.LSTG_ROOM_CNT, L.LSTG_ROOM_NUM, L.LSTG_DST, L.LSTG_TYPE_SALE, L.LSTG_LEASE, L.LSTG_LEASE_M, L.LSTG_LEASE_AMT, L.LSTG_FLOOR, L.LSTG_PARK_YN, L.LSTG_LAT, L.LSTG_LNG, L.LSTG_DEL, L.LSTG_REG_DATE, L.LSTG_PROD_STAT, L.LSTG_NM, L.LSTG_TYPE_CODE1, L.RENTAL_PTY_ID, L.LSTG_POSTAL, L.LSTG_FEE FROM LISTING L WHERE L.LSTG_DEL = 'N'
AND L.MBR_CD = #{pagingVO.detailSearch.mbrCd}
AND L.LSTG_NM LIKE '%' || #{pagingVO.detailSearch.searchBuildingName} || '%'
AND L.LSTG_ROOM_NUM LIKE '%' || #{pagingVO.detailSearch.searchRoomNum} || '%'
AND L.LSTG_PROD_STAT = #{pagingVO.detailSearch.searchStatus}
AND L.LSTG_TYPE_SALE = #{pagingVO.detailSearch.searchType}
AND L.LSTG_LEASE >= #{pagingVO.detailSearch.searchDepositMin}
AND L.LSTG_LEASE <= #{pagingVO.detailSearch.searchDepositMax}
AND L.LSTG_LEASE_AMT >= #{pagingVO.detailSearch.searchDepositMin}
AND L.LSTG_LEASE_AMT <= #{pagingVO.detailSearch.searchDepositMax}
AND L.LSTG_LEASE_M >= #{pagingVO.detailSearch.searchMonthlyMin}
AND L.LSTG_LEASE_M <= #{pagingVO.detailSearch.searchMonthlyMax}
AND L.LSTG_SALE >= #{pagingVO.detailSearch.searchSaleMin}
AND L.LSTG_SALE <= #{pagingVO.detailSearch.searchSaleMax}
AND L.LSTG_REG_DATE >= TO_DATE(#{pagingVO.detailSearch.searchRegDateFrom}, 'YYYY-MM-DD')
AND L.LSTG_REG_DATE <= TO_DATE(#{pagingVO.detailSearch.searchRegDateTo}, 'YYYY-MM-DD') + 1
) A_PAGING WHERE RNUM BETWEEN #{pagingVO.firstRecordIndex} AND #{pagingVO.lastRecordIndex}

